import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"瞻卬","description":"","frontmatter":{"title":"瞻卬","date":"2026-11-09T00:00:00.000Z","seq":30,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/瞻卬.md","filePath":"blogs/诗经·大雅/瞻卬.md"}'),o={name:"blogs/诗经·大雅/瞻卬.md"};function c(l,a,n,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="瞻卬" tabindex="-1">瞻卬 <a class="header-anchor" href="#瞻卬" aria-label="Permalink to &quot;瞻卬&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">瞻卬昊天，则不我惠。孔填不宁，降此大厉。邦靡有定，士民其瘵。</p><p class="poem-stanza">蟊贼蟊疾，靡有夷届。罪罟不收，靡有夷瘳。</p><p class="poem-stanza">人有土田，女反有之。人有民人，女覆夺之。此宜无罪，女反收之。</p><p class="poem-stanza">彼宜有罪，女覆说之。</p><p class="poem-stanza">哲夫成城，哲妇倾城。懿厥哲妇，为枭为鸱。妇有长舌，维厉之阶。</p><p class="poem-stanza">乱匪降自天，生自妇人。匪教匪诲，时维妇寺。</p><p class="poem-stanza">鞫人忮忒。谮始竞背。岂曰不极？伊胡为慝？如贾三倍，君子是识。</p><p class="poem-stanza">妇无公事，休其蚕织。</p><p class="poem-stanza">天何以剌？何神不富？舍尔介狄，维予胥忌。不吊不祥，威仪不类。</p><p class="poem-stanza">人之云亡，邦国殄瘁。</p><p class="poem-stanza">天之降罔，维其优矣。人之云亡，心之忧矣。天之降罔，维其几矣。</p><p class="poem-stanza">人之云亡，心之悲矣。</p><p class="poem-stanza">觱沸槛泉，维其深矣。心之忧矣，宁自今矣？不自我先，不自我后。</p><p class="poem-stanza">藐藐昊天，无不克巩。无忝皇祖，式救尔后。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
